import json, html, pathlib
from collections import Counter
root=pathlib.Path(__file__).resolve().parent
entries=json.loads((root/'reference_100.json').read_text(encoding='utf-8'))['entries']
assert len(entries)==100 and len({x['id'] for x in entries})==100
products={29:('MORPH','https://nilo-morph-lab.onrender.com/'),50:('LINKLOOM','https://nilo-linkloom-lab.onrender.com/'),70:('PLOTCRAFT','https://nilo-plotcraft-lab.onrender.com/')}
assert all(entries[x-1]['id']==x for x in products)
from collections import OrderedDict
groups=OrderedDict()
for e in entries:groups.setdefault(e['category'],[]).append(e)
assert len(groups)==10 and all(len(x)==10 for x in groups.values())
