def esc(s):return html.escape(str(s),quote=True)
sections=[]
for i,(cat,arr) in enumerate(groups.items()):
 rows=[]
 for e in arr:
  j=e['id'];published=j in products
  if published:
   nm,link=products[j];tail=f'<a class="go" href="{esc(link)}" target="_blank" rel="noopener noreferrer" aria-label="{nm}を開く（新しいタブ）">{nm} ↗</a>'
   state='<span class="entry-meta">公開デモ</span>'
  else:tail='';state='<span class="entry-meta">開発候補</span>'
  rows.append(f'<li class="entry{" is-public" if published else ""}" data-entry data-stage="{"public" if published else "candidate"}" data-search="{esc((e["reference_service"]+" "+cat+" "+(products[j][0] if published else "")).lower())}"><span class="ordinal">{j:03d}</span><span class="entry-name">{esc(e["reference_service"])}</span>{state}{tail}</li>')
 sections.append(f'<section class="collection" data-collection><header><h3>{esc(cat)}</h3><small>{i+1:02d} / 10</small></header><ul class="rows" style="list-style:none;padding:0;margin:0">{"".join(rows)}</ul></section>')
lead=[]
for i,(num,name,description,link) in enumerate([(1,'MORPH','画像・ファイルを端末上で一括処理。','https://nilo-morph-lab.onrender.com/'),(2,'PLOTCRAFT','データからグラフを制作・書き出し。','https://nilo-plotcraft-lab.onrender.com/'),(3,'LINKLOOM','自分のページをデザインし、HTMLで所有。','https://nilo-linkloom-lab.onrender.com/')]):
 lead.append(f'<a class="lead-card" href="{esc(link)}" target="_blank" rel="noopener noreferrer" aria-label="{name}を新しいタブで開く"><span class="num">LIVE DEMO / 0{i+1}</span><h3>{name}</h3><p>{esc(description)}</p><span class="go">サイトを開く ↗</span></a>')
script='''
(()=>{'use strict';const input=document.querySelector('#search'),buttons=[...document.querySelectorAll('[data-filter]')],entries=[...document.querySelectorAll('[data-entry]')],sections=[...document.querySelectorAll('[data-collection]')],counter=document.querySelector('#visible-count'),empty=document.querySelector('#no-results');let stage='all';function update(){const q=input.value.trim().toLocaleLowerCase();let shown=0;for(const entry of entries){const yes=(!q||entry.dataset.search.includes(q))&&(stage==='all'||entry.dataset.stage===stage);entry.hidden=!yes;if(yes)shown++}for(const group of sections){group.hidden=![...group.querySelectorAll('[data-entry]')].some(e=>!e.hidden)}counter.textContent=String(shown);empty.hidden=shown!==0}for(const b of buttons)b.addEventListener('click',()=>{stage=b.dataset.filter;for(const x of buttons)x.setAttribute('aria-pressed',String(x===b));update()});input.addEventListener('input',update);update()})();
'''
